let lastDraftPreset={};
function applyDraftPreset(){
 const type=document.getElementById("draftType").value, lang=language==="en"?"en":"hi";
 const preset=(draftPresets[type]||draftPresets.general)[lang];
 ["subject","facts","request"].forEach(key=>{
  const field=document.getElementById("draft"+key.charAt(0).toUpperCase()+key.slice(1));
  if(field&&(!field.value.trim()||field.value===lastDraftPreset[key]))field.value=preset[key];
  lastDraftPreset[key]=preset[key];
 });
}
applyDraftPreset();
function buildDraft(){
 const en=language==="en", typeKey=document.getElementById("draftType").value;
 const office=document.getElementById("draftOffice").value.trim()||(en?"[Relevant officer / office]":"[संबंधित अधिकारी/कार्यालय]");
 const subject=document.getElementById("draftSubject").value.trim()||(en?"[Application subject]":"[आवेदन का विषय]");
 const facts=document.getElementById("draftFacts").value.trim()||(en?"[Factual description of events]":"[घटनाओं का तथ्यात्मक विवरण]");
 const request=document.getElementById("draftRequest").value.trim()||(en?"[Your request]":"[अपना अनुरोध]");
 const enclosures=document.getElementById("draftEnclosures").value.trim();
 const date=new Intl.DateTimeFormat(en?"en-IN":"hi-IN",{day:"numeric",month:"long",year:"numeric"}).format(new Date());
 const templates={
  general:{en:"I wish to bring the following facts to your attention:",hi:"मैं निम्न तथ्य आपके संज्ञान में लाना चाहता/चाहती हूँ:"},
  police:{en:"I wish to submit this complaint. The details below are stated to the best of my knowledge. Any estimate or information received from another person should be clearly identified as such:",hi:"मैं यह शिकायत प्रस्तुत कर रहा/रही हूँ। नीचे दिए गए विवरण मेरी जानकारी के अनुसार हैं। किसी अनुमान या दूसरे व्यक्ति से मिली जानकारी को स्पष्ट रूप से उसी रूप में बताया जाना चाहिए:"},
  records:{en:"I am writing to request access to the following record/document:",hi:"मैं निम्न रिकॉर्ड/दस्तावेज़ की प्रति/उपलब्धता हेतु अनुरोध कर रहा/रही हूँ:"},
  fircopy:{en:"I respectfully request information about the procedure for obtaining a copy of the relevant FIR:",hi:"मैं संबंधित FIR की प्रति प्राप्त करने की प्रक्रिया और उपलब्धता के संबंध में जानकारी देने का अनुरोध करता/करती हूँ:"},
  zeroFir:{en:"I wish to give information about a suspected cognizable offence. BNSS Section 173(1) provides that such information may be given to the officer in charge of a police station irrespective of the area where the offence was committed. I request that the information be received and dealt with according to law:",hi:"मैं एक संभावित संज्ञेय अपराध के संबंध में सूचना देना चाहता/चाहती हूँ। BNSS की धारा 173(1) के अनुसार ऐसी सूचना अपराध घटित होने के क्षेत्र की परवाह किए बिना किसी पुलिस थाने के प्रभारी अधिकारी को दी जा सकती है। निवेदन है कि सूचना प्राप्त कर कानून के अनुसार कार्रवाई की जाए:"},
  refusal:{en:"I previously attempted to provide information about a suspected cognizable offence, but state accurately what response was given and when. Under BNSS Section 173(4), where the officer in charge refuses to record such information, the substance may be sent in writing by post to the Superintendent of Police concerned. This draft is a representation only; seek legal advice on the correct recipient and next steps:",hi:"मैंने पहले एक संभावित संज्ञेय अपराध की सूचना देने का प्रयास किया था। कृपया मिली प्रतिक्रिया और तारीख़ का सही विवरण नीचे दें। BNSS की धारा 173(4) के अनुसार, यदि थाना प्रभारी ऐसी सूचना दर्ज करने से मना करे, तो सूचना का सार लिखित रूप में डाक से संबंधित पुलिस अधीक्षक को भेजा जा सकता है। यह केवल एक आवेदन का प्रारूप है; सही अधिकारी और आगे की प्रक्रिया के लिए विधिक सलाह लें:"},
  cyber:{en:"I am submitting a follow-up regarding a cybercrime report and provide these general details:",hi:"मैं साइबर अपराध की पूर्व शिकायत के संबंध में फॉलो-अप प्रस्तुत कर रहा/रही हूँ और निम्न सामान्य विवरण दे रहा/रही हूँ:"}
 };
 const intro=(templates[typeKey]||templates.general)[en?"en":"hi"];
 const output=en?"To,\n"+office+"\n\nSubject: "+subject+"\n\nSir/Madam,\n"+intro+"\n\n"+facts+"\n\nI respectfully request that: "+request+"\n\nPlease provide an acknowledgement or reference number for this submission, if applicable.\n\n"+(enclosures?"Enclosures (list only documents actually attached): "+enclosures+"\n\n":"") +"Date: "+date+"\n\nApplicant name: [Fill offline]\nApplicant address/contact: [Fill offline if required]\nSignature: __________________\n\nNote: Review every statement and attach only genuine, relevant records. This draft has not been submitted.":"सेवा में,\n"+office+"\n\nविषय: "+subject+"\n\nमहोदय/महोदया,\n"+intro+"\n\n"+facts+"\n\nअतः निवेदन है कि: "+request+"\n\nकृपया लागू प्रक्रिया के अनुसार इस आवेदन की प्राप्ति/संदर्भ संख्या प्रदान करें।\n\n"+(enclosures?"संलग्नक (केवल वही दस्तावेज़ लिखें जो वास्तव में साथ लगाए गए हैं): "+enclosures+"\n\n":"")+"दिनांक: "+date+"\n\nआवेदक का नाम: [ऑफलाइन भरें]\nपत्राचार पता/संपर्क: [आवश्यक हो तो ऑफलाइन भरें]\nहस्ताक्षर: __________________\n\nनोट: हर तथ्य जाँच लें और केवल वास्तविक, प्रासंगिक रिकॉर्ड ही संलग्न करें। यह ड्राफ्ट अभी जमा नहीं हुआ है।";
 document.getElementById("draftText").textContent=output;return output;
}
// Keep the preview, copy, and print output synchronized with the latest form values.
const draftFieldIds=["draftType","draftOffice","draftSubject","draftFacts","draftRequest","draftEnclosures"];
draftFieldIds.forEach(id=>{
 const field=document.getElementById(id);
 if(!field)return;
 field.addEventListener(id==="draftType"?"change":"input",()=>{
  if(id==="draftType")applyDraftPreset();
  buildDraft();
  const status=document.getElementById("draftStatus");
  if(status){status.textContent="";status.hidden=true;}
  const generateButton=document.getElementById("generateDraft");
  if(generateButton)generateButton.textContent=translations[language].generate;
  const copyButton=document.getElementById("copyDraft");
  if(copyButton)copyButton.textContent=translations[language].copyDraft;
 });
});
document.getElementById("generateDraft").addEventListener("click",()=>{
 const subject=document.getElementById("draftSubject").value.trim(),facts=document.getElementById("draftFacts").value.trim(),request=document.getElementById("draftRequest").value.trim();
 if(!subject||!facts||!request){const status=document.getElementById("draftStatus");status.textContent=translations[language].requiredFields;status.hidden=false;return}
 const status=document.getElementById("draftStatus");status.textContent="";status.hidden=true;
 buildDraft();document.getElementById("generateDraft").textContent=translations[language].generated;
});
document.getElementById("clearDraft").addEventListener("click",()=>{
 ["draftOffice","draftSubject","draftFacts","draftRequest","draftEnclosures"].forEach(id=>document.getElementById(id).value="");
 document.getElementById("draftType").value="general";
 lastDraftPreset={};applyDraftPreset();
 document.getElementById("draftStatus").textContent=translations[language].cleared;
 document.getElementById("draftStatus").hidden=false;
 document.getElementById("generateDraft").textContent=translations[language].generate;
 document.getElementById("copyDraft").textContent=translations[language].copyDraft;
 buildDraft();
});
async function copyTextWithFallback(value){
 try{
  if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(value);return true;}
 }catch{}
 const temporary=document.createElement("textarea");
 temporary.value=value;
 temporary.setAttribute("readonly","");
 temporary.style.position="fixed";
 temporary.style.opacity="0";
 temporary.style.pointerEvents="none";
 document.body.appendChild(temporary);
 temporary.focus();
 temporary.select();
 temporary.setSelectionRange(0,temporary.value.length);
 let copied=false;
 try{copied=document.execCommand("copy")}catch{}
 temporary.remove();
 return copied;
}
document.getElementById("copyDraft").addEventListener("click",async()=>{
 const button=document.getElementById("copyDraft");
 const copied=await copyTextWithFallback(document.getElementById("draftText").textContent);
 button.textContent=translations[language][copied?"copied":"copyUnavailable"];
 const status=document.getElementById("draftStatus");
 if(status){status.textContent=copied?translations[language].copied:translations[language].copyUnavailable;status.hidden=false;}
});
applyDraftLanguage();


document.querySelectorAll("[data-dashboard-tab]").forEach(tab=>{
 tab.addEventListener("click",()=>{
  const target=tab.dataset.dashboardTab;
  document.querySelectorAll("[data-dashboard-tab]").forEach(item=>{
   const active=item===tab;
   item.classList.toggle("dash-active",active);
   item.setAttribute("aria-pressed",active?"true":"false");
  });
  document.querySelectorAll("[data-dashboard-view]").forEach(view=>{
   view.hidden=view.dataset.dashboardView!==target;
  });
 });
});

/* Interactive preparation checklist progress (session-only; no data is transmitted). */
(()=>{
 const box=document.querySelector(".checklist");
 if(!box)return;
 const checks=[...box.querySelectorAll('input[type="checkbox"]')];
 const text=document.getElementById("checklistProgressText");
 const percent=document.getElementById("checklistProgressPercent");
 const bar=document.getElementById("checklistProgressBar");
 const update=()=>{
  const done=checks.filter(item=>item.checked).length;
  const en=document.documentElement.lang==="en";
  if(text)text.textContent=en?done+" of "+checks.length+" complete":done+"/"+checks.length+" पूरे";
  if(percent)percent.textContent=Math.round(done/checks.length*100)+"%";
  if(bar)bar.style.width=(done/checks.length*100)+"%";
 };
 checks.forEach(item=>item.addEventListener("change",update));
 new MutationObserver(update).observe(document.documentElement,{attributes:true,attributeFilter:["lang"]});
 update();
})();
